'use strict'

import transitionManager from '../service/transition-manager'
import { TopMenu } from '../model/top-menu'
import Link from '../model/link'
import InputManager from '../service/input-manager'
import HitboxManager from '../service/hitbox-manager'
import { TRANSITION_MAP_DRAG, TRANSITION_LEVEL_EXIT, TRANSITION_CAVE_STAIRS_UP, SOUND_OVERWORLD, SOUND_MUSIC_DUNGEON, NES_PIXEL, MAP_TYPE_WORLD, DIRECTION_NORTH, DIRECTION_SOUTH, DIRECTION_EAST, DIRECTION_WEST, LINK_DIRECTION_EAST, LINK_DIRECTION_NORTH, LINK_DIRECTION_SOUTH, LINK_DIRECTION_WEST, LINK_ACTION_MOVE, LINK_ACTION_USE_ITEM_A, LINK_ACTION_USE_ITEM_B, GAME_TOP_MENU_HEIGHT, SPRITE_TEXT_COLOR_WHITE, TILE_WIDTH, TILE_HEIGHT, TILES_PER_LINE, TILES_PER_COLUMN, CAVE_MONEY_GAME, CAVE_PAY_TO_TALK, CAVE_DOOR_REPAIR, OPPOSITE_DIRECTIONS, MAP_TYPES_LEVELS, MAP_TYPE_CAVERNS, SOUND_LOW_HEALTH } from '../constant'
import soundManager from '../service/sound-manager'
import resource from '../resource'
import worldManager from '../service/world-manager'
import { TileTransition } from '../model/tile-transition'
import { Dialog, ItemPick, SecretRupees, MoneyGame, PayToTalk, DoorRepair, Death, TriforceTaken, openCurtain, CURTAIN_RESTART_BLACK_FRAMES } from '../model/transition'
import { isCaveClosed } from '../model/cave'
import { GameOverMenu } from './game-over-menu'
import { updateEnemies, resetRoomPlaces, leaveRoom, forgetRecentRooms, forgetKills } from '../model/enemy'
import { drawCenteredText } from './screen-text'
import { listenMenuKeys } from './menu-keys'
import { InventoryMenu } from '../model/inventory-menu'
import { bringIn } from '../model/whistle'
import { deathRgb, sceneryRgb, FLASH_PALETTE } from '../model/death-colours'
import { prepareRoom, walkIn, walkAlone, carryOut, updateDoors, placeRoomItem, updateRoomItem, updateOldMan, oldManTalking, screamOfBoss, triforceImage } from '../model/dungeon'
import { stairsReached, stairsPlace, cellarLeft, cellarEntry, cellarExit, roomFade, CELLAR_FADE } from '../model/cellar'
import clock from '../service/clock'
import { stepSlowTimers, resetSlowTimers } from '../model/slow-timers'
import { backOnLostPath, resetLostPaths, screenAgain } from '../model/lost-paths'
import { DIRECTION_VECTORS } from '../model/enemies/common'
import { createLowLifeBeep, updateLowLifeBeep } from '../model/low-life'

const FRAME = 1000 / 60
const FADE_STEP_FRAMES = 10
// Out of a cellar from its right half (x from $80), Link goes to the room of its 2nd table (bank 5, $8EF6)
const CELLAR_RIGHT = 0x80 * NES_PIXEL
// CONTINUE: the menu still shown after Start, and the hearts Link starts again with (measured)
const CONTINUE_MENU_FRAMES = 63
const CONTINUE_LIFE = 3

// The arrows, in the order they win when several are held
const MOVE_DIRECTIONS = {
  [InputManager.ACTION_LINK_MOVE_NORTH]: LINK_DIRECTION_NORTH,
  [InputManager.ACTION_LINK_MOVE_SOUTH]: LINK_DIRECTION_SOUTH,
  [InputManager.ACTION_LINK_MOVE_EAST]: LINK_DIRECTION_EAST,
  [InputManager.ACTION_LINK_MOVE_WEST]: LINK_DIRECTION_WEST
}

class Game {
  constructor () {
    const startingPosition = worldManager.findStartingPosition()
    if (!startingPosition) {
      throw new Error('No starting position found')
    }
    const map = startingPosition.map
    const link = new Link(map.x + startingPosition.tileColumn * TILE_WIDTH, map.y + startingPosition.tileLine * TILE_HEIGHT, TILE_WIDTH, TILE_HEIGHT)
    link.map = map
    resetRoomPlaces()
    resetLostPaths()
    resetSlowTimers()

    this.topMenu = new TopMenu(link)
    this.inventoryMenu = new InventoryMenu(link, TILES_PER_COLUMN * TILE_HEIGHT)
    // this.topMenu.initializeMap(map)

    this.map = map
    this.nextMap = undefined

    this.link = link
    this.link.addEventListener(Link.EVENT_ITEM_A_CHANGED, () => InputManager.enable(InputManager.ACTION_LINK_USE_ITEM_A))
    this.link.addEventListener(Link.EVENT_ITEM_B_CHANGED, () => InputManager.enable(InputManager.ACTION_LINK_USE_ITEM_B))

    this.isStarted = false
    this.transitionPlaying = false
    // The beeps of low life, silent on the stairs into a cave or out of it (see low-life.js)
    this.lowLifeBeep = createLowLifeBeep()
    this.onStairs = false

    // Death: steps of the animation (see Death), then the game over menu
    this.deathEffect = undefined
    // Going in or out of a level: how much of the screen is open (see openCurtain)
    this.curtain = undefined
    // A piece of the Triforce taken: what Link holds up ({ name, x, y }), and whether the scenery is white
    this.heldItem = undefined
    this.sceneryFlash = false
    // Down to a cellar or out of it: the colours of the scenery (palettes 2 and 3), and Link not drawn
    this.sceneryFade = undefined
    this.linkHidden = false
    this.gameOverMenu = undefined
    // Set by the page: what "retry" in the game over menu does
    this.onRetry = undefined
  }

  start () {
    this.map.init()
    this.link.hitbox = HitboxManager.compute(this.link)
    this.map.spawnEnemies(this.link)

    InputManager.setMapping()
    InputManager.startDetection()
    InputManager.currentMappingName = InputManager.MAPPING_MAIN

    this.isStarted = true
    // Start opens and closes the inventory; left / right choose the item of B there
    this.stopMenuKeys = listenMenuKeys({
      [InputManager.ACTION_START]: () => this.toggleInventory(),
      [InputManager.ACTION_LINK_MOVE_WEST]: () => this.inventoryMenu.move(-1),
      [InputManager.ACTION_LINK_MOVE_EAST]: () => this.inventoryMenu.move(1)
    })

    soundManager.play(resource.getSound(SOUND_OVERWORLD))

    // this.link.itemA = ItemManager.create(ItemManager.WOODEN_SWORD, 0, 0)
  }

  // Before another game replaces this one (import): no more keys, sounds or animations from it
  stop () {
    this.isStarted = false
    InputManager.reset()
    resource.stopAllSounds()
    this.map.reset()
    this.nextMap?.reset()
    this.link.stopWalking()
    this.gameOverMenu?.dispose()
    this.stopMenuKeys?.()
    this.stopMenuKeys = undefined
  }

  // Not while something else goes on (screen change, dialog, death); the game waits meanwhile
  toggleInventory () {
    if (!this.isStarted || this.transitionPlaying || this.gameOverMenu || this.deathEffect) {
      return
    }
    if (!this.inventoryMenu.isOpen) {
      this.link.resetActions()
      this.link.stopWalking()
      InputManager.clear()
    }
    this.inventoryMenu.toggle()
  }

  async die () {
    this.transitionPlaying = true
    this.link.resetActions()
    InputManager.clear()
    await new Death().play(this)
    if (!this.isStarted) {
      return // Stopped meanwhile (game imported)
    }
    this.gameOverMenu = new GameOverMenu(() => this.continue(), () => this.onRetry?.())
  }

  // After a game over, keeping the items, with 3 hearts (measured with 5 containers): the menu stays 63 frames, then
  // the game starts again as a level does (mode $03: black, the curtain, the music). In a level (under its stairs
  // too), at its entrance, Link coming up its south door; at the surface, at the starting position
  async continue () {
    await this.framesFrom(clock.now)(CONTINUE_MENU_FRAMES)
    this.gameOverMenu = undefined
    this.deathEffect = undefined
    this.link.dead = false
    this.link.grabbed = undefined
    this.link.currentLife = Math.min(CONTINUE_LIFE, this.link.totalLife)
    this.sceneryFade = undefined
    this.linkHidden = false
    InputManager.clear()
    if (MAP_TYPES_LEVELS.includes(this.map.type)) {
      await this.backToEntrance(true)
      return
    }
    const startingPosition = worldManager.findStartingPosition()
    this.map.reset()
    this.map = startingPosition.map
    this.link.map = this.map
    this.link.x = this.map.x + startingPosition.tileColumn * TILE_WIDTH
    this.link.y = this.map.y + startingPosition.tileLine * TILE_HEIGHT
    this.link.tile = undefined
    this.link.direction = DIRECTION_SOUTH
    this.link.hitbox = HitboxManager.compute(this.link)
    this.map.init()
    await openCurtain(this, CURTAIN_RESTART_BLACK_FRAMES)
    soundManager.play(resource.getSound(SOUND_OVERWORLD))
    this.map.spawnEnemies(this.link)
    this.transitionPlaying = false
  }

  draw (context, x, y, width, height) {
    if (!this.isStarted) {
      return
    }

    context.clearRect(x, y, width, height)

    if (this.gameOverMenu) {
      this.gameOverMenu.draw(context, width, height)
      return
    }

    // The inventory pushes the top menu and the screen down
    context.save()
    context.translate(0, this.inventoryMenu.offset)

    // Translate contexte to draw map behind top menu
    context.translate(0, GAME_TOP_MENU_HEIGHT)

    context.translate(-this.map.x, -this.map.y)
    this.map.draw(context, this.sceneryRecolour())
    if (this.mapDragTransitionPlaying) {
      this.nextMap.draw(context)
    }
    if (this.deathEffect) {
      this.drawDeath(context)
    } else if (this.curtain === undefined && !(this.mapDragTransitionPlaying && this.map.room)) {
      // From one room of a level to the next, Link is not drawn while the screen scrolls: gone under the frame
      // of a door, he comes out of the opposite one
      this.drawLink(context)
    }
    context.translate(this.map.x, this.map.y)

    // The curtain: black, then the screen open from its middle
    if (this.curtain !== undefined) {
      const open = Math.max(0, this.curtain) * NES_PIXEL
      const side = this.map.width / 2 - open
      context.fillStyle = 'black'
      context.fillRect(0, 0, side, this.map.height)
      context.fillRect(this.map.width - side, 0, side, this.map.height)
      // Holding the piece of the Triforce, Link stays on the screen as it closes
      if (this.heldItem) {
        context.translate(-this.map.x, -this.map.y)
        this.drawLink(context)
        context.translate(this.map.x, this.map.y)
      }
      if (this.curtain < 0) {
        context.fillRect(0, -GAME_TOP_MENU_HEIGHT, this.map.width, GAME_TOP_MENU_HEIGHT)
        context.restore()
        return
      }
    }

    if (this.deathEffect?.gameOver) {
      context.fillStyle = 'black'
      context.fillRect(0, 0, this.map.width, this.map.height)
      drawCenteredText(context, 'game over', SPRITE_TEXT_COLOR_WHITE, this.map.width, (this.map.height - TILE_HEIGHT / 2) / 2)
    }

    context.translate(0, -GAME_TOP_MENU_HEIGHT)
    this.topMenu.draw(context)
    context.restore()
    this.inventoryMenu.draw(context)
  }

  // Link, and what he holds up
  drawLink (context) {
    if (this.linkHidden) {
      return
    }
    this.link.draw(context, 0, 0, this.link.action)
    const item = this.heldItem
    if (item) {
      resource.getSprite(`item_${item.name}`)?.images[triforceImage()]?.draw(context, item.x, item.y, TILE_WIDTH, TILE_HEIGHT)
    }
  }

  // While Link dies, or when the scenery flashes (a piece of the Triforce taken), the tiles in the colours of the ROM
  // (see death-colours.js)
  sceneryRecolour () {
    const type = this.map.cellar ? 'cellar' : this.map.type
    // Going down to a cellar or up out of it (see enterCellar)
    const fade = this.sceneryFade
    if (fade) {
      return image => resource.recolourImage(image, `fade:${type}:${fade.flat().join('')}`, colours => sceneryRgb(colours, type, fade))
    }
    if (this.sceneryFlash) {
      return image => resource.recolourImage(image, `flash:${type}`, colours => sceneryRgb(colours, type, FLASH_PALETTE))
    }
    const step = this.deathEffect?.palette
    if (step === undefined) {
      return undefined
    }
    return image => resource.recolourImage(image, `death:${type}:${step}`, colours => deathRgb(colours, type, step))
  }

  // Link spins on the red scenery, turns grey (his colour, see Link.colour), then becomes a sparkle
  drawDeath (context) {
    const effect = this.deathEffect
    if (effect.hidden) {
      return
    }
    if (effect.sparkleFrame !== undefined) {
      resource.getSprite('link_death')?.images[effect.sparkleFrame]?.draw(context, this.link.x, this.link.y, this.link.width, this.link.height)
      return
    }
    this.link.draw(context, 0, 0, this.link.action)
  }

  async process () {
    if (!this.isStarted) {
      return
    }

    const quiet = this.inventoryMenu.isShown || this.onStairs || !!this.deathEffect
    if (updateLowLifeBeep(this.lowLifeBeep, this.link.currentLife, quiet, clock.now)) {
      soundManager.play(resource.getSound(SOUND_LOW_HEALTH))
    }

    if (this.transitionPlaying) {
      return
    }

    // The game waits while the inventory is shown
    if (this.inventoryMenu.isShown) {
      this.inventoryMenu.update()
      if (!this.inventoryMenu.isShown) {
        InputManager.clear()
      }
      return
    }

    // Process static transitions
    this.map.closed = isCaveClosed(this.map, this.link)
    // In a cave Link waits while the character talks; in a level, he goes on (see updateOldMan)
    if (!this.map.closed && !this.map.room && this.map.character && this.map.character.enabled && !this.map.character.hasStoppedTalking()) {
      this.transitionPlaying = true
      this.link.resetActions()
      const transition = new Dialog()
      await transition.play(this.link)
      this.transitionPlaying = false
      return
    }

    // Nothing is picked or taken in the whirlwind
    const carried = !!this.link.carried
    for (const item of this.map.closed || carried ? [] : this.map.items) {
      if (this.link.canPick(item)) {
        this.transitionPlaying = true
        this.link.resetActions()
        await this.createItemTransition(item).play(this.link, item)
        this.transitionPlaying = false
        return
      }
    }

    // Through a bombed wall, Link is carried to the edge of the screen, which then scrolls
    if (this.map.crossing) {
      this.map.crossing = undefined
      this.transitionPlaying = true
      this.link.resetActions()
      await carryOut(this.link)
      this.transitionPlaying = false
      return
    }

    // Process move transitions
    const linkTile = HitboxManager.getLinkTile(this.map, this.link)
    if (linkTile && linkTile !== this.link.tile) {
      linkTile.tileTransition.enabled = true
    }
    this.link.tile = linkTile
    const linkFrontTile = HitboxManager.getLinkFrontTile(this.map, this.link)
    let tileTransition
    if (this.link.tile && !linkFrontTile && !carried) {
      tileTransition = this.createDynamicMapDragTileTransition()
      this.mapDragTransitionPlaying = tileTransition.start === TRANSITION_MAP_DRAG
    }
    // A hidden entrance leads nowhere until it is found
    if (this.link.tile && linkFrontTile && !this.link.tile.isHidden && !carried) {
      tileTransition = this.link.tile.tileTransition
    }
    const transitionStart = tileTransition?.start ? transitionManager.get(tileTransition.start) : undefined
    if (tileTransition && tileTransition.enabled && tileTransition.start && (transitionStart?.canStart?.(this.link, this.link.tile) ?? true)) {
      this.transitionPlaying = true
      this.link.resetActions()
      // What the room remembers of its enemies killed; going in or out of a level, the last rooms are forgotten, and
      // out of it, the enemies killed in it (see leaveRoom)
      leaveRoom(this.map)
      const targetType = tileTransition.targetMapType ?? this.map.type
      const changesArea = MAP_TYPES_LEVELS.includes(this.map.type) !== MAP_TYPES_LEVELS.includes(targetType) && targetType !== MAP_TYPE_CAVERNS && this.map.type !== MAP_TYPE_CAVERNS
      if (changesArea) {
        forgetRecentRooms()
        if (MAP_TYPES_LEVELS.includes(this.map.type)) {
          forgetKills(worldManager[this.map.type].flat())
        }
      }
      // As in the original game, the enemies vanish as soon as Link leaves
      this.map.clearEnemies()
      this.nextMap = tileTransition.getTargetMap()
      this.nextMap.init()
      // A room of a dungeon: its doors as Link comes in, through the door of his side when the screen scrolls
      const scrolled = tileTransition.start === TRANSITION_MAP_DRAG
      this.onStairs = !scrolled
      prepareRoom(this.nextMap, scrolled ? OPPOSITE_DIRECTIONS[this.link.direction] : undefined)
      // Back on the same screen (the lost woods): it scrolls in again from beyond the edge Link leaves by
      let shift
      if (scrolled && this.nextMap === this.map) {
        const [dx, dy] = DIRECTION_VECTORS[this.link.direction]
        shift = { x: dx * this.map.width, y: dy * this.map.height }
        this.nextMap = screenAgain(this.map)
      }
      if (transitionStart) {
        await transitionStart.play(this.link, this.map, this.nextMap, shift)
      }
      this.map.reset()
      this.map.offsetX = 0
      this.map.offsetY = 0
      this.map = tileTransition.getTargetMap()
      this.map.offsetX = 0
      this.map.offsetY = 0
      this.link.map = this.map
      this.nextMap = undefined
      this.link.x = tileTransition.getTargetPosition().x
      this.link.y = tileTransition.getTargetPosition().y
      // In or out of a level, the screen opens like a curtain before Link shows
      if (changesArea) {
        await openCurtain(this)
      }
      const transitionEnd = transitionManager.get(tileTransition.end)
      if (transitionEnd) {
        await transitionEnd.play(this.link)
      }
      // Into a room, Link walks in on his own, once the screen has scrolled; into a level, up from the bottom edge
      // of its first room, through its south door (measured: from y = $DD to $CD), with the music of the dungeons
      if ((scrolled || changesArea) && this.map.room) {
        this.mapDragTransitionPlaying = false
        if (!scrolled) {
          this.link.direction = DIRECTION_NORTH
          soundManager.play(resource.getSound(SOUND_MUSIC_DUNGEON))
        }
        await walkIn(this.map, this.link)
      }
      this.link.tile = HitboxManager.getLinkTile(this.map, this.link)
      this.link.tile.tileTransition.enabled = false
      this.link.map = this.map
      if (this.map.cave === CAVE_DOOR_REPAIR && !this.map.emptied) {
        new DoorRepair().play(this.link)
      }
      this.map.spawnEnemies(this.link)
      placeRoomItem(this.map)
      screamOfBoss(this.map)
      this.transitionPlaying = false
      this.mapDragTransitionPlaying = false
      this.onStairs = false
      tileTransition.enabled = false
      return
    }

    // Process link and the enemies, the slow timers first (as the ROM does, bank 7 $E51E)
    stepSlowTimers()
    this.link.update(this.map)
    updateEnemies(this.map, this.link)
    updateDoors(this.map, this.link)
    updateRoomItem(this.map, this.link)
    updateOldMan(this.map, this.link)
    if (this.link.currentLife <= 0) {
      await this.die()
      return
    }
    // Down the stairs of a room, up out of a cellar
    if (stairsReached(this.map, this.link)) {
      await this.enterCellar()
      return
    }
    if (cellarLeft(this.map, this.link)) {
      await this.leaveCellar()
      return
    }
    // A piece of the Triforce taken: Link holds it up, then leaves the level
    if (this.map.triforceTaken) {
      await this.takeTriforce()
      return
    }
    // A wallmaster took Link back into the wall: the level starts again at its entrance
    if (this.map.carriedOff) {
      await this.backToEntrance()
      return
    }
    const whirlwind = this.map.whistles.find(effect => effect.leaving)
    if (whirlwind) {
      await this.warp(whirlwind.target)
      return
    }
    // While the old man of a room talks, Link waits (see updateOldMan)
    if (oldManTalking(this.map)) {
      this.link.resetActions()
      this.link.stopWalking()
      return
    }
    this.processLinkActions()
  }

  // The whirlwind carries Link off the right edge: the screen of the level scrolls in from the right, as the
  // next one would (measured in the ROM), and another whirlwind brings him in from the left edge
  async warp (target) {
    this.transitionPlaying = true
    this.link.resetActions()
    this.map.clearEnemies()
    const nextMap = worldManager.getMap(MAP_TYPE_WORLD, target.column, target.line)
    nextMap.init()
    this.nextMap = nextMap
    this.mapDragTransitionPlaying = true
    this.link.direction = DIRECTION_EAST
    const shift = { x: this.map.x + this.map.width - nextMap.x, y: this.map.y - nextMap.y }
    await transitionManager.get(TRANSITION_MAP_DRAG).play(this.link, this.map, nextMap, shift)
    this.map.reset()
    this.map.offsetX = 0
    this.map.offsetY = 0
    nextMap.offsetX = 0
    nextMap.offsetY = 0
    this.map = nextMap
    this.nextMap = undefined
    this.link.map = nextMap
    this.link.x = nextMap.x
    this.link.y = nextMap.y + target.tileLine * TILE_HEIGHT
    this.link.hitbox = HitboxManager.compute(this.link)
    this.link.tile = HitboxManager.getLinkTile(nextMap, this.link)
    nextMap.spawnEnemies(this.link)
    bringIn(nextMap, this.link, target)
    this.mapDragTransitionPlaying = false
    this.transitionPlaying = false
  }

  // Back to the first room of the level, coming up its south door as from the surface (the ROM starts the level
  // again, mode $03: Link at the bottom edge, y = $DD, walks in to $CD). After a death, the music of the dungeons
  // starts again as he walks in (measured)
  async backToEntrance (music = false) {
    this.transitionPlaying = true
    this.link.resetActions()
    this.link.grabbed = undefined
    this.map.carriedOff = false
    this.map.wallmasterHolding = false
    this.map.reset()
    forgetRecentRooms()
    const entrance = worldManager[this.map.type].flat().find(map => map?.room?.entrance) ?? this.map
    entrance.init()
    prepareRoom(entrance)
    this.map = entrance
    this.link.map = entrance
    this.link.x = entrance.x + 7.5 * TILE_WIDTH
    this.link.y = entrance.y + 10 * TILE_HEIGHT
    this.link.direction = DIRECTION_NORTH
    await openCurtain(this, CURTAIN_RESTART_BLACK_FRAMES)
    if (music) {
      soundManager.play(resource.getSound(SOUND_MUSIC_DUNGEON))
    }
    await walkIn(entrance, this.link)
    this.link.hitbox = HitboxManager.compute(this.link)
    this.link.tile = HitboxManager.getLinkTile(entrance, this.link)
    entrance.spawnEnemies(this.link)
    placeRoomItem(entrance)
    this.transitionPlaying = false
  }

  async takeTriforce () {
    this.transitionPlaying = true
    const item = this.map.triforceTaken
    this.map.triforceTaken = undefined
    this.link.resetActions()
    InputManager.clear()
    this.map.clearEnemies()
    await new TriforceTaken().play(this, item)
    await this.leaveLevel()
    this.transitionPlaying = false
  }

  // Out of the level, as by the south door of its entrance: the screen black, then the surface opens like a curtain
  // and Link comes up the stairs of the entrance
  async leaveLevel () {
    const rooms = worldManager[this.map.type].flat().filter(Boolean)
    const exit = rooms.find(map => map.room?.exit).room.exit
    leaveRoom(this.map)
    forgetRecentRooms()
    forgetKills(rooms)
    this.map.reset()
    const surface = worldManager.getMap(MAP_TYPE_WORLD, exit.column, exit.line)
    surface.init()
    this.map = surface
    this.link.map = surface
    this.link.x = surface.x + exit.tileColumn * TILE_WIDTH
    this.link.y = surface.y + exit.tileLine * TILE_HEIGHT
    await openCurtain(this)
    await transitionManager.get(TRANSITION_CAVE_STAIRS_UP).play(this.link)
    this.link.hitbox = HitboxManager.compute(this.link)
    this.link.tile = HitboxManager.getLinkTile(surface, this.link)
    if (this.link.tile) {
      this.link.tile.tileTransition.enabled = false
    }
    surface.spawnEnemies(this.link)
  }

  // Down the stairs of a room to its cellar, measured in $22 of level 1 (frames from the one Link is on the stairs):
  // he is no longer drawn, the room darkens in 3 steps of 10 frames from frame 15, stays black, the cellar lights up
  // in 3 steps from frame 72, and at frame 92 Link shows at the top of its ladder and goes down it on his own
  async enterCellar () {
    this.transitionPlaying = true
    const room = this.map
    const target = room.room.cellar
    const cellar = worldManager.getMap(room.type, target.column, target.line)
    const until = this.framesFrom(clock.now)
    this.link.resetActions()
    this.link.stopWalking()
    const stairs = stairsPlace(room)
    this.link.x = stairs.x
    this.link.y = stairs.y
    leaveRoom(room)
    room.clearEnemies()
    this.linkHidden = true
    await this.fade(until, 15, roomFade(room.type))
    room.reset()
    cellar.init()
    this.map = cellar
    this.link.map = cellar
    const entry = cellarEntry(cellar)
    this.link.x = entry.x
    this.link.y = entry.y
    this.link.direction = DIRECTION_SOUTH
    await this.fade(until, 72, [...CELLAR_FADE].reverse().slice(1))
    await until(92)
    this.sceneryFade = undefined
    this.linkHidden = false
    await walkAlone(this.link, entry.walk)
    this.link.hitbox = HitboxManager.compute(this.link)
    this.link.tile = HitboxManager.getLinkTile(cellar, this.link)
    cellar.spawnEnemies(this.link)
    this.transitionPlaying = false
  }

  // Up the ladder out of the cellar, measured in $7F of level 1 (frames from the one Link is above y = $41): the
  // cellar darkens in 3 steps from frame 14, the room lights up in 3 steps from frame 73, Link standing at the place
  // of the 3rd table of the cellar, and the music of the dungeon starts again at frame 95
  async leaveCellar () {
    this.transitionPlaying = true
    const cellar = this.map
    const until = this.framesFrom(clock.now)
    this.link.resetActions()
    this.link.stopWalking()
    cellar.clearEnemies()
    this.linkHidden = true
    await this.fade(until, 14, CELLAR_FADE)
    cellar.reset()
    // The room of the stairs on its left (table 1) or on its right (table 2), as Link goes out
    const number = cellar.cellar.rooms[this.link.x - cellar.x >= CELLAR_RIGHT ? 1 : 0]
    const room = worldManager.getMap(cellar.type, number & 15, number >> 4)
    room.init()
    prepareRoom(room)
    this.map = room
    this.link.map = room
    const exit = cellarExit(cellar, room)
    this.link.x = exit.x
    this.link.y = exit.y
    this.link.direction = DIRECTION_SOUTH
    await this.fade(until, 73, [...roomFade(room.type)].reverse().slice(1))
    await until(93)
    this.sceneryFade = undefined
    this.linkHidden = false
    await until(95)
    soundManager.play(resource.getSound(SOUND_MUSIC_DUNGEON))
    this.link.hitbox = HitboxManager.compute(this.link)
    this.link.tile = HitboxManager.getLinkTile(room, this.link)
    room.spawnEnemies(this.link)
    placeRoomItem(room)
    this.transitionPlaying = false
  }

  // Waits until frame n from the start
  framesFrom (start) {
    return frame => new Promise(resolve => clock.delay(resolve, start + frame * FRAME - clock.now))
  }

  // The scenery in these colours, each for 10 frames from frame `from` (the last one stays)
  async fade (until, from, steps) {
    for (let k = 0; k < steps.length; k++) {
      await until(from + k * FADE_STEP_FRAMES)
      this.sceneryFade = steps[k]
    }
    await until(from + steps.length * FADE_STEP_FRAMES)
  }

  // What touching an item does depends on the cave
  createItemTransition (item) {
    if (this.map.cave === CAVE_MONEY_GAME) {
      return new MoneyGame()
    }
    if (this.map.cave === CAVE_PAY_TO_TALK) {
      return new PayToTalk()
    }
    if (item.rupees) {
      return new SecretRupees()
    }
    return new ItemPick()
  }

  createDynamicMapDragTileTransition () {
    // Out of the level, at the bottom edge of its entrance (measured: y = $DD), to the stairs of the surface
    const exit = this.map.room?.exit
    if (exit && this.link.direction === DIRECTION_SOUTH) {
      return new TileTransition(TRANSITION_LEVEL_EXIT, MAP_TYPE_WORLD, exit.column, exit.line, exit.tileColumn, exit.tileLine, TRANSITION_CAVE_STAIRS_UP)
    }
    let targetMapColumn
    let targetMapLine
    let targetTileColumn
    let targetTileLine
    if (this.link.direction === DIRECTION_EAST) {
      targetMapColumn = this.map.column + 1
      targetMapLine = this.map.line
      targetTileColumn = 0
      targetTileLine = (this.link.y % (TILES_PER_COLUMN * TILE_HEIGHT)) / TILE_HEIGHT
    }
    if (this.link.direction === DIRECTION_NORTH) {
      targetMapColumn = this.map.column
      targetMapLine = this.map.line - 1
      targetTileColumn = (this.link.x % (TILES_PER_LINE * TILE_WIDTH)) / TILE_WIDTH
      targetTileLine = TILES_PER_COLUMN - 1
    }
    if (this.link.direction === DIRECTION_SOUTH) {
      targetMapColumn = this.map.column
      targetMapLine = this.map.line + 1
      targetTileColumn = (this.link.x % (TILES_PER_LINE * TILE_WIDTH)) / TILE_WIDTH
      targetTileLine = 0
    }
    if (this.link.direction === DIRECTION_WEST) {
      targetMapColumn = this.map.column - 1
      targetMapLine = this.map.line
      targetTileColumn = TILES_PER_LINE - 1
      targetTileLine = (this.link.y % (TILES_PER_COLUMN * TILE_HEIGHT)) / TILE_HEIGHT
    }
    // The lost woods and the lost hills: back on the same screen, coming in by the opposite edge (see lost-paths.js)
    if (backOnLostPath(this.map, this.link.direction)) {
      targetMapColumn = this.map.column
      targetMapLine = this.map.line
    }
    return new TileTransition(TRANSITION_MAP_DRAG, this.map.type, targetMapColumn, targetMapLine, targetTileColumn, targetTileLine)
  }

  processLinkActions () {
    // Link stands still while he uses an item, and can't help being pushed back, carried (whirlwind, wallmaster) or
    // on the raft
    this.link.moving = false
    if (this.link.usingItem || this.link.knockback || this.link.carried || this.link.grabbed || this.link.raft) {
      this.link.resetActions()
      return
    }

    // The arrows held: the way Link goes is chosen as in the ROM (see Link.chooseWay)
    const moves = Object.keys(MOVE_DIRECTIONS)
    if (moves.some(action => this.link.hasAction(action))) {
      const held = moves.filter(move => InputManager.isHeld(move) || this.link.hasAction(move)).map(move => MOVE_DIRECTIONS[move])
      this.link.walk(this.map, held)
      this.link.startWalking()
      this.link.moving = true
    } else {
      this.link.stopWalking()
    }

    if (this.link.actions.length === 0) {
      this.link.action = LINK_ACTION_MOVE
      return
    }
    for (const action of [...this.link.actions]) {
      if (moves.includes(action)) {
        this.link.removeAction(action)
      } else {
        this.processAction(action)
      }
    }
  }

  getLinkActionFromInput (inputAction) {
    switch (inputAction) {
      case InputManager.ACTION_LINK_MOVE_EAST:
      case InputManager.ACTION_LINK_MOVE_NORTH:
      case InputManager.ACTION_LINK_MOVE_SOUTH:
      case InputManager.ACTION_LINK_MOVE_WEST:
        return LINK_ACTION_MOVE
      case InputManager.ACTION_LINK_USE_ITEM_A:
        return LINK_ACTION_USE_ITEM_A
      case InputManager.ACTION_LINK_USE_ITEM_B:
        return LINK_ACTION_USE_ITEM_B
      default:
        return undefined
    }
  }

  processAction (action) {
    switch (action) {
      case InputManager.ACTION_LINK_USE_ITEM_A:
        this.link.useItemA()
        break
      case InputManager.ACTION_LINK_USE_ITEM_B:
        this.link.useItemB(this.map)
        break
      case InputManager.ACTION_MENU_CLOSE:

        break
      case InputManager.ACTION_MENU_MOVE_BOTTOM:

        break
      case InputManager.ACTION_MENU_MOVE_LEFT:

        break
      case InputManager.ACTION_MENU_MOVE_RIGHT:

        break
      case InputManager.ACTION_MENU_MOVE_TOP:

        break
      case InputManager.ACTION_MENU_OPEN:

        break
    }

    this.link.removeAction(action)
  }

  processInput () {
    if (!this.isStarted) {
      return
    }

    if (this.transitionPlaying || this.inventoryMenu.isShown) {
      return
    }

    const action = InputManager.getCurrentAction()
    if (action) {
      this.link.addAction(action)
    }
  }
}

export default Game
