'use strict'

import { isBlocked } from '../../service/collision'
import soundManager from '../../service/sound-manager'
import resource from '../../resource'
import { chooseDrop, SPARKLE } from '../drop'
import { ROOM } from '../room-box'
import { NES_PIXEL, TILE_WIDTH, TILE_HEIGHT, SOUND_BOSS_HIT, SOUND_BOSS_SCREAM_3, SOUND_ENNEMY_DIE } from '../../constant'
import { Enemy, STATE_DYING, FLASH_STEPS, TERRAIN_INSET, WEAPON_FLAME, drawImage, inset } from './common'
import { Fireball } from './projectile'
import { WAYS, EAST, WEST, SOUTH, NORTH, wayTowards, wanderWay, oppositeWay, randomByte } from './moldorm'

// Manhandla, read in the ROM (object $3C, bank 4 $A187; made by $A10C) and measured in $4D of level 3:
// - 5 objects: its mouths up (slot 1), down (2), left (3), right (4), 16 NES pixels from its centre (5), at the place
//   of the 5th enemy of the room, out of no cloud; the scream of level 3 sounds ($0601 $40);
// - it goes one of 8 ways (that of the moldorms, $B24E), all its parts together, a NES pixel along each of its axes
//   when its speed carries over ($80: every other frame); every 16 frames ($28 of the centre) it turns, towards Link
//   (a random byte from $80, $B31A) or at random ($B388); a part going out of the room ($0346-$0349) or into the
//   scenery sends them all back the other way ($B2CD, $0385);
// - each mouth opens and closes as it goes ($0451: a random 0 to 3 more each frame, and the pixels gone; bit 4) and,
//   as it closes, spits a fireball ($56, a heart, aimed at Link from x + 4) once in 8 ($19 from $E0), when slot 7 is
//   free (5 fireballs at most, from slot 11 down);
// - a mouth has $40 of life (4 hits of the wooden sword), takes them with no knockback, flashes, and the sample $02
//   sounds ($8000); the boomerang and the flame do nothing. The centre's flash is put back to 0: the sword hits it at
//   every frame it reaches it, down to 0 of life, when it dies and lives again at once ($A24C), the sound of a death
//   going ($0602 $20, $0604 $02, asked again at each of those frames; here, once a thrust);
// - a mouth killed while others live becomes a sparkle ($5D) and the others go $80 faster ($0383: 0.5 NES pixel a
//   frame more on each axis); the last one dies as any enemy and leaves an item (class 3), and the centre becomes a
//   sparkle with it ($A26A). Measured in $4D: a thrust hit two mouths and the centre; the sparkle in the place of the
//   mouth, $0601 $02, $0602 $20, $0604 $02; the speed $100, $180, $200 the next frame; the last mouth and the centre
//   dying together, with $0603 $80 more (a sound the game does not have)
const MANHANDLA = { life: 4, contactDamage: 1 }
const MOUTHS = ['top', 'bottom', 'left', 'right']
const CENTRE = 'centre'
// The places of the parts from the centre ($A105, $A107), NES pixels
const PLACES = { top: [0, -16], bottom: [0, 16], left: [-16, 0], right: [16, 0], centre: [0, 0] }
const SPEED = 0x80
const FASTER = 0x80
const TURN_FRAMES = 16
const TOWARDS_LINK = 0x80
const MOUTH_FRAMES_BIT = 0x10
const SHOT_CHANCE = 0xe0
const MAX_FIREBALLS = 5
const FIREBALL_DAMAGE = 1
const MOUTH_X = 4
const FLASH_FRAMES = 32
// Its sprites (tiles $E0-$EC, sprite palette 1): the mouth up open and shut ($E8, $EA and their mirrors), turned down,
// left ($E0 $E2, $E4 $E6), right; the centre ($EC and its mirror). Measured: the image of a frame is that of the
// open bit of the frame before
const SPRITES = { top: 'manhandla_mouth_move', bottom: 'manhandla_mouth_down', left: 'manhandla_mouth_left', right: 'manhandla_mouth_right', centre: 'manhandla_body_move' }

// What the 5 parts share: their way, its timer, their speed
export class ManhandlaBody {
  constructor (random) {
    this.random = random
    this.parts = []
    this.way = WAYS[Math.floor(random() * 8)]
    this.timer = 0
    this.speed = SPEED
    this.fraction = 0
    this.back = false
  }

  get centre () {
    return this.parts.find(part => part.role === CENTRE)
  }

  get mouths () {
    return this.parts.filter(part => part.role !== CENTRE && !part.isDead && part.state !== STATE_DYING)
  }

  // One frame of the centre: the turn, then the pixels each part goes
  update (map, target) {
    if (this.back) {
      this.way = oppositeWay(this.way)
      this.back = false
    }
    if (--this.timer <= 0) {
      this.timer = TURN_FRAMES
      const centre = this.centre
      this.way = randomByte(this.random) >= TOWARDS_LINK ? wayTowards(this.way, target, centre) : wanderWay(this.way, this.random)
    }
    this.fraction += this.speed
    const pixels = Math.floor(this.fraction / 0x100)
    this.fraction -= pixels * 0x100
    const dx = ((this.way & EAST ? 1 : 0) - (this.way & WEST ? 1 : 0)) * pixels * NES_PIXEL
    const dy = ((this.way & SOUTH ? 1 : 0) - (this.way & NORTH ? 1 : 0)) * pixels * NES_PIXEL
    // A sparkle stays where it is
    for (const part of this.parts.filter(part => !part.isDead && part.state !== STATE_DYING)) {
      part.x += dx
      part.y += dy
      part.mouthCount += Math.floor(this.random() * 4) + pixels
      if (part.blocked(map, this.way)) {
        this.back = true
      }
    }
  }

  // A mouth killed: the others go faster; the last one, the centre dies with it
  mouthKilled (mouth, link) {
    const left = this.mouths.filter(part => part !== mouth)
    soundManager.play(resource.getSound(SOUND_ENNEMY_DIE))
    if (left.length > 0) {
      chooseDrop(SPARKLE, link.killRecord, this.random)
      mouth.setState(STATE_DYING)
      this.speed += FASTER
      return
    }
    mouth.drop = chooseDrop(mouth.type, link.killRecord, mouth.random, false, mouth.slot)
    mouth.setState(STATE_DYING)
    const centre = this.centre
    chooseDrop(SPARKLE, link.killRecord, this.random)
    centre.setState(STATE_DYING)
  }
}

export class Manhandla extends Enemy {
  constructor (type, x, y, body, role, random = Math.random) {
    super(type, x, y, MANHANDLA, random)
    this.body = body
    this.role = role
    this.mouthCount = 0
    this.mouthOpen = 0
    this.flash = 0
  }

  // The 5 parts, the centre at (x, y)
  static parts (type, x, y, random = Math.random) {
    const body = new ManhandlaBody(random)
    for (const role of [...MOUTHS, CENTRE]) {
      const [dx, dy] = PLACES[role]
      body.parts.push(new Manhandla(type, x + dx * NES_PIXEL, y + dy * NES_PIXEL, body, role, random))
    }
    return [...body.parts]
  }

  start () {
    this.setState('moving')
    if (this.role === CENTRE) {
      soundManager.play(resource.getSound(SOUND_BOSS_SCREAM_3))
    }
  }

  // Going that way, out of the room ($6F29: a part already out may come back in), or into the scenery ahead ($6F73)
  blocked (map, way) {
    const rx = this.x - map.x
    const ry = this.y - map.y
    const out = (rx < ROOM.left ? WEST : 0) | (rx > ROOM.right ? EAST : 0) | (ry < ROOM.top ? NORTH : 0) | (ry > ROOM.bottom ? SOUTH : 0)
    if ((way & out) !== 0) {
      return true
    }
    if (out !== 0) {
      return false
    }
    const ahead = NES_PIXEL * 2
    const x = this.x + ((way & EAST ? 1 : 0) - (way & WEST ? 1 : 0)) * ahead
    const y = this.y + ((way & SOUTH ? 1 : 0) - (way & NORTH ? 1 : 0)) * ahead
    return isBlocked(map, inset(x, y, TILE_WIDTH, TILE_HEIGHT, TERRAIN_INSET))
  }

  get isVulnerable () {
    return this.isActive && this.flash === 0
  }

  stun () {}

  hit (link, { damage, weapon } = {}) {
    if (weapon === WEAPON_FLAME) {
      return
    }
    // The centre, its flash put back to 0, is hit at every frame the sword reaches it; at 0, it dies and lives again at
    // once, the sound of a death going
    if (this.role === CENTRE) {
      this.life = Math.max(0, this.life - (damage ?? link.swordDamage))
      if (this.life === 0 && this.lastDeath !== link.swordSwing) {
        this.lastDeath = link.swordSwing
        soundManager.play(resource.getSound(SOUND_ENNEMY_DIE))
      }
      return
    }
    if (damage === undefined) {
      this.lastSwing = link.swordSwing
    }
    this.life -= damage ?? link.swordDamage
    this.flash = FLASH_FRAMES
    this.flashSteps = FLASH_STEPS
    this.flashType = link.map?.type
    soundManager.play(resource.getSound(SOUND_BOSS_HIT))
    if (this.life <= 0) {
      this.body.mouthKilled(this, link)
    }
  }

  process (map, link) {
    if (this.flash > 0) {
      this.flash--
    }
    super.process(map, link)
  }

  act (map, link) {
    if (this.role === CENTRE) {
      this.body.update(map, map.target ?? link)
      return
    }
    // As it closes, maybe a fireball
    const open = (this.mouthCount & MOUTH_FRAMES_BIT) ? 1 : 0
    if (open !== this.mouthOpen) {
      this.mouthOpen = open
      const fireballs = map.projectiles.filter(projectile => projectile instanceof Fireball && !projectile.done).length
      if (open === 0 && randomByte(this.random) >= SHOT_CHANCE && fireballs < MAX_FIREBALLS) {
        map.projectiles.push(new Fireball(this.x + MOUTH_X * NES_PIXEL, this.y, link, { damage: FIREBALL_DAMAGE }))
      }
    }
  }

  drawBody (context) {
    drawImage(context, resource.getSprite(SPRITES[this.role]), this.role === CENTRE ? 0 : this.mouthOpen, this.x, this.y, this.width, this.height)
  }
}
