'use strict'

import { NES_PIXEL, TILE_WIDTH, TILE_HEIGHT } from '../constant'

// The rooms under the levels, seen from the side (see docs/rom-analysis.md, Le bloc d'un niveau), as measured in $7F
// of level 1. map.cellar: { rooms, exit, ladders } (tools/levels/build.js). Link goes up and down on the ladders only
// (on the axis of one), and walks on the floors only: a line of the grid whose squares are open (not bricks) above
// bricks or a ladder. He comes in from the top of the ladder of column 3 and goes out by it

// Link's y on the screen in NES pixels for a line of squares (as in the rooms)
const NES_TOP = 0x3d
const SQUARE = 16
// Above it, Link is out (measured: at y = $3F)
export const CELLAR_OUT_Y = 0x41

const nesX = (map, x) => (x - map.x) / NES_PIXEL
const nesY = (map, y) => (y - map.y) / NES_PIXEL + NES_TOP

// The bricks are the only squares that block (tools/levels/build.js)
function isBrick (map, column, line) {
  const tile = map.getTile(column, line)
  return !tile || tile.blockPoints.length > 0
}

function isLadder (map, column, line) {
  return map.cellar.ladders.some(ladder => ladder.column === column && line >= ladder.top && line <= ladder.bottom)
}

// The squares under a span of 16 NES pixels from x
const columnsOf = x => [Math.floor(x / SQUARE), Math.floor((x + SQUARE - 1) / SQUARE)]

// Link at (x, y) in a cellar: true if he may be there coming from where he is, undefined out of a cellar
export function cellarAllows (map, link, x, y) {
  if (!map.cellar) {
    return undefined
  }
  const nx = nesX(map, x)
  const ny = nesY(map, y)
  if (y !== link.y) {
    // On a ladder, from the square above its top (the floor it leads to, or the way out) to its bottom
    const ladder = map.cellar.ladders.find(l => l.column * SQUARE === nx)
    return !!ladder && ny >= NES_TOP + (ladder.top - 1) * SQUARE && ny <= NES_TOP + ladder.bottom * SQUARE
  }
  const offset = ny - NES_TOP
  const line = offset / SQUARE
  if (offset % SQUARE !== 0 || line < 1) {
    return false
  }
  return columnsOf(nx).every(column => !isBrick(map, column, line) && (isBrick(map, column, line + 1) || isLadder(map, column, line + 1)))
}

// Link at the stairs of a room that leads down to a cellar (measured: on them, x = $80, y = $8D in $22), on their axis
// and less than one step of his walk from them (he goes 1 or 2 NES pixels a frame)
const STAIRS_NEAR = 2 * NES_PIXEL

export function stairsPlace (map) {
  const stairs = map.room?.cellar?.stairs
  return stairs && { x: map.x + stairs.column * TILE_WIDTH, y: map.y + stairs.line * TILE_HEIGHT }
}

export function stairsReached (map, link) {
  const place = stairsPlace(map)
  if (!place) {
    return false
  }
  const dx = Math.abs(link.x - place.x)
  const dy = Math.abs(link.y - place.y)
  return (dx === 0 && dy < STAIRS_NEAR) || (dy === 0 && dx < STAIRS_NEAR)
}

// Link up the ladder he came in by, out of the cellar
export function cellarLeft (map, link) {
  return !!map.cellar && nesY(map, link.y) < CELLAR_OUT_Y
}

// Where Link comes in: at the top of the ladder of column 3 (x = $30, y = $41), then down to $5D on his own
const CELLAR_IN_Y = 0x5d

export function cellarEntry (map) {
  const ladder = map.cellar.ladders[0]
  return { x: map.x + ladder.column * TILE_WIDTH, y: map.y + (CELLAR_OUT_Y - NES_TOP) * NES_PIXEL, walk: (CELLAR_IN_Y - CELLAR_OUT_Y) * NES_PIXEL }
}

// Where Link comes out in the room above (3rd table of the cellar, see tools/levels/build.js)
export function cellarExit (cellar, room) {
  return { x: room.x + cellar.cellar.exit.x * NES_PIXEL, y: room.y + (cellar.cellar.exit.y - NES_TOP) * NES_PIXEL }
}

// The colours of the scenery while the screen darkens and lights up again (palettes 2 and 3, measured in $22 and $7F
// of level 1, $69 and $0F of level 3), from the lit one: each step lasts 10 frames
const ROOM_FADES = {
  level1: [
    [[0x0f, 0x0c, 0x0c, 0x1c], [0x0f, 0x11, 0x0c, 0x1c]],
    [[0x0f, 0x0f, 0x0c, 0x0c], [0x0f, 0x02, 0x0c, 0x0c]],
    [[0x0f, 0x0f, 0x0f, 0x0f], [0x0f, 0x0f, 0x0f, 0x0f]]
  ],
  level3: [
    [[0x0f, 0x0b, 0x0b, 0x1b], [0x0f, 0x17, 0x0b, 0x1b]],
    [[0x0f, 0x0f, 0x0b, 0x0b], [0x0f, 0x06, 0x0b, 0x0b]],
    [[0x0f, 0x0f, 0x0f, 0x0f], [0x0f, 0x0f, 0x0f, 0x0f]]
  ]
}

export function roomFade (type) {
  return ROOM_FADES[type] ?? ROOM_FADES.level1
}
export const CELLAR_FADE = [
  [[0x0f, 0x00, 0x00, 0x10], [0x0f, 0x00, 0x00, 0x10]],
  [[0x0f, 0x0f, 0x00, 0x00], [0x0f, 0x0f, 0x00, 0x00]],
  [[0x0f, 0x0f, 0x0f, 0x0f], [0x0f, 0x0f, 0x0f, 0x0f]]
]
