'use strict'

import soundManager from '../../service/sound-manager'
import resource from '../../resource'
import { chooseDrop, SPARKLE } from '../drop'
import { ROOM } from '../room-box'
import { NES_PIXEL, SOUND_ENNEMY_HIT, SOUND_ENNEMY_DIE } from '../../constant'
import { Enemy, STATE_DYING, FLASH_STEPS, drawImage } from './common'

// The moldorms, read in the ROM (object $41, bank 4 $9498; made by $93E2): two worms of 5 rings, slots 1 to 5 and
// 6 to 10, the head last (5 and 10), all at x = $80, y = $70 at first, out of no cloud. A ring goes its way, one of
// 8, a NES pixel along each of its axes when its speed ($80 in $041F) carries over (bank 4, $B288): every other
// frame. Every 16 frames ($28 of the head), the head turns, and each ring takes the way the ring before it had
// then ($0380 + slot), the ring behind the head the way the head had 16 frames before. The head turns towards Link
// (state 2, $B31A) or at random (state 3, $B388), 8 times, then picks again: at random 3 times out of 4. A ring at
// the edge of the room going out of it (x from $20 to $D0, y from $5D to $BD, $0346-$0349) is stopped in its way;
// the head turns back the next time it turns, the others go on until the ring before gives them another way.
// A ring has $20 of life (2 hits of the wooden sword); killed, it is whole again, and the last ring of its worm
// comes to its place to die as a sparkle ($5D): the worm is a ring shorter. The head alone dies as any enemy, and
// leaves an item (class 3). It takes half a heart from Link; the boomerang does nothing to it
const MOLDORM = { life: 2, contactDamage: 0.5 }
export const MOLDORM_PLACE = { x: 0x80, y: 0x70 - 0x3d }
export const WORM_RINGS = 5
// The 8 ways, turning clockwise from the north (table $B24E), as the bits of the ROM: 1 east, 2 west, 4 south, 8 north
export const WAYS = [0x08, 0x09, 0x01, 0x05, 0x04, 0x06, 0x02, 0x0a]
export const EAST = 1
export const WEST = 2
export const SOUTH = 4
export const NORTH = 8
const SPEED = 0x80
const TURN_FRAMES = 16
const TURNS = 8
const CHASE = 'chase'
const WANDER = 'wander'
// A random byte under $40 makes it wander
const WANDER_CHANCE = 0x40
// Turning at random: a random byte from $A0, straight on; from $50, a way clockwise; under, the other
const STRAIGHT = 0xa0
const CLOCKWISE = 0x50

export const randomByte = random => Math.floor(random() * 256)
const wayIndex = way => Math.max(0, WAYS.indexOf(way))
const at = index => WAYS[((index % 8) + 8) % 8]
export const oppositeWay = way => at(wayIndex(way) + 4)

// A turn at random ($B388): straight on, a way clockwise or anticlockwise
export function wanderWay (way, random) {
  const value = randomByte(random)
  return value >= STRAIGHT ? way : at(wayIndex(way) + (value >= CLOCKWISE ? 1 : -1))
}

// The way of the head towards Link ($B31A): nothing to do if it already goes that way or one next to it; otherwise
// the first of the way anticlockwise, its own, the way clockwise that shares an axis with Link's and adds none
// (their bits make less than 7), clockwise when none does
export function wayTowards (way, target, ring) {
  const x = target.x === ring.x ? 0 : target.x > ring.x ? EAST : WEST
  const y = target.y === ring.y ? 0 : target.y > ring.y ? SOUTH : NORTH
  const wanted = x | y
  const index = wayIndex(way)
  if ([1, 0, -1].some(k => at(index + k) === wanted)) {
    return way
  }
  for (const k of [-1, 0, 1]) {
    const candidate = at(index + k)
    if ((candidate & wanted) !== 0 && (candidate | wanted) < 7) {
      return candidate
    }
  }
  return at(index + 1)
}

// A worm: its rings from the last one to the head, what its head does, and its timer
export class Worm {
  constructor (random) {
    this.rings = []
    this.random = random
    this.mode = CHASE
    // The first time, the head picks what to do at once ($042C = 1)
    this.turns = 1
    this.timer = 0
    this.back = 0 // The way back of the head stopped at the edge ($03BC)
  }

  get head () {
    return this.rings[this.rings.length - 1]
  }

  // One frame of the head (bank 4, $9510 and $952B), after the target of the walkers (Link, or the point opposite
  // him: $61, $62, see walker.js)
  update (target) {
    if (this.timer > 0 && --this.timer > 0) {
      return
    }
    this.timer = TURN_FRAMES
    if (--this.turns <= 0) {
      this.mode = randomByte(this.random) < WANDER_CHANCE ? WANDER : CHASE
      this.turns = TURNS
      // The rings follow only once the one behind the head goes somewhere
      if (!(this.rings[this.rings.length - 2]?.way)) {
        return
      }
    } else {
      this.turn(target)
    }
    this.follow()
  }

  turn (target) {
    const head = this.head
    if (this.mode === CHASE) {
      head.way = wayTowards(head.way, target, head)
      return
    }
    head.way = wanderWay(head.way, this.random)
  }

  // Each ring takes the way the ring before it had ($9540)
  follow () {
    const head = this.head
    if (this.back) {
      head.way = this.back
      this.back = 0
    }
    for (let i = 0; i < this.rings.length - 1; i++) {
      this.rings[i].way = this.rings[i + 1].followed
    }
    for (const ring of this.rings) {
      ring.followed = ring.way
    }
  }
}

export class Moldorm extends Enemy {
  constructor (type, x, y, worm, random = Math.random) {
    super(type, x, y, MOLDORM, random)
    this.worm = worm
    this.way = 0
    this.followed = 0
    this.speed = 0
  }

  // The head goes somewhere at random from the start ($9D, $A2)
  static worms (type, x, y, counts, random = Math.random) {
    return counts.map(count => {
      const worm = new Worm(random)
      for (let i = 0; i < count; i++) {
        worm.rings.push(new Moldorm(type, x, y, worm, random))
      }
      worm.head.way = WAYS[Math.floor(random() * 8)]
      worm.head.followed = worm.head.way
      return worm
    })
  }

  start () {
    this.setState('moving')
  }

  // The boomerang does nothing to it
  stun () {}

  act (map, link) {
    if (this === this.worm.head) {
      this.worm.update(map.target ?? link)
    }
    this.move(map)
  }

  move (map) {
    this.speed += SPEED
    if (this.speed < 0x100) {
      return
    }
    this.speed -= 0x100
    if (!this.way) {
      return
    }
    this.x += ((this.way & EAST ? 1 : 0) - (this.way & WEST ? 1 : 0)) * NES_PIXEL
    this.y += ((this.way & SOUTH ? 1 : 0) - (this.way & NORTH ? 1 : 0)) * NES_PIXEL
    // At the edge of the room ($6F29, $6F73)
    const rx = this.x - map.x
    const ry = this.y - map.y
    const out = (rx < ROOM.left ? WEST : 0) | (rx >= ROOM.right ? EAST : 0) | (ry < ROOM.top ? NORTH : 0) | (ry >= ROOM.bottom ? SOUTH : 0)
    if ((this.way & out) && this === this.worm.head) {
      this.worm.back = oppositeWay(this.way)
    }
  }

  // No knockback; killed, the last ring of the worm dies in its place
  hit (link, { damage, byBomb } = {}) {
    if (damage === undefined) {
      this.lastSwing = link.swordSwing
    }
    this.life -= damage ?? link.swordDamage
    this.flashSteps = FLASH_STEPS
    this.flashType = link.map?.type
    if (this.life > 0) {
      soundManager.play(resource.getSound(SOUND_ENNEMY_HIT))
      return
    }
    soundManager.play(resource.getSound(SOUND_ENNEMY_DIE))
    const worm = this.worm
    if (worm.rings.length === 1) {
      worm.rings = []
      this.drop = chooseDrop(this.type, link.killRecord, this.random, byBomb, this.slot)
      this.setState(STATE_DYING)
      return
    }
    this.life = MOLDORM.life
    const last = worm.rings.shift()
    last.x = this.x
    last.y = this.y
    last.flashSteps = this.flashSteps
    last.flashType = this.flashType
    chooseDrop(SPARKLE, link.killRecord, this.random)
    last.setState(STATE_DYING)
  }

  drawBody (context) {
    drawImage(context, resource.getSprite('moldorm_move'), 0, this.x, this.y, this.width, this.height)
  }
}
