'use strict'

import soundManager from '../../service/sound-manager'
import resource from '../../resource'
import { chooseDrop } from '../drop'
import { TILE_WIDTH, NES_PIXEL, DIRECTION_EAST, DIRECTION_WEST, DIRECTION_NORTH, DIRECTION_SOUTH, SOUND_ENNEMY_HIT, SOUND_ENNEMY_DIE } from '../../constant'
import { Enemy, DIRECTION_VECTORS, DIRECTIONS, STATE_DYING, STATE_DEAD, FLASH_STEPS, drawImage, pick, randomInt, canWalkTo } from './common'
import { chooseWay, avoidObstacle } from './walker'
import { Gel } from './gel'

// The big blob of the dungeons, read in the ROM (object $13, bank 4 $84CB) and measured in $7B of level 3: it hops
// on the grid as a gel (see gel.js), slower ($18: 0.375 NES pixel a frame), and waits 24, 40, 56 or 72 frames
// (table $85F6). Its image changes every 8 frames. It takes a heart from Link.
// A hit that does not kill it ($852C): if it is on the grid across the blow, it slides the way of the blow, 4 NES
// pixels a frame, until the scenery or the wall stops it (state 1, $85FE; measured: 22 frames from x = $80 to the
// wall at $D0), then it becomes two gels ($84F9: objects $14 where it is, in two free slots), going across the way it
// went: north and south after a blow sideways, west and east after one up or down (their cloud and their slide: see
// Gel.split). Otherwise it is cut at once. The
// gels are one more enemy in the room ($034E); the zol is not counted as killed
const ZOL = { life: 2, contactDamage: 1, turnRate: 0x20 }
const SPEED = 0x18
const SPEED_UNIT = 0x40
const PAUSES = [24, 40, 56, 72]
const FIRST_PAUSE = 5
const MAX_TURN_FRAMES = 255
const IMAGE_FRAMES = 8
const SLIDE_SPEED = 4 * NES_PIXEL
const COLOURS = { level3: 'green' }
const SLOTS = 11
const mod = (value, divisor) => ((value % divisor) + divisor) % divisor
const STATE_HOPPING = 'hopping'
const STATE_SLIDING = 'sliding'
const STATE_CUT = 'cut'
const ACROSS = {
  [DIRECTION_EAST]: [DIRECTION_SOUTH, DIRECTION_NORTH],
  [DIRECTION_WEST]: [DIRECTION_SOUTH, DIRECTION_NORTH],
  [DIRECTION_NORTH]: [DIRECTION_WEST, DIRECTION_EAST],
  [DIRECTION_SOUTH]: [DIRECTION_WEST, DIRECTION_EAST]
}

export class Zol extends Enemy {
  constructor (type, x, y, random = Math.random) {
    super(type, x, y, ZOL, random)
    this.direction = pick(random, DIRECTIONS)
    this.pause = FIRST_PAUSE
    this.turnFrames = randomInt(random, 0, MAX_TURN_FRAMES)
    this.fraction = 0
    this.frames = 0
    this.uncounted = false // Cut in two: dead, but not killed
  }

  start () {
    this.setState(STATE_HOPPING)
  }

  hit (link, { damage, direction, byBomb } = {}) {
    if (damage === undefined) {
      this.lastSwing = link.swordSwing
    }
    this.life -= damage ?? link.swordDamage
    if (this.life <= 0) {
      soundManager.play(resource.getSound(SOUND_ENNEMY_DIE))
      this.drop = chooseDrop(this.type, link.killRecord, this.random, byBomb, this.slot)
      this.setState(STATE_DYING)
      return
    }
    soundManager.play(resource.getSound(SOUND_ENNEMY_HIT))
    this.flashSteps = FLASH_STEPS
    this.flashType = link.map?.type
    this.direction = direction ?? link.direction
    const sideways = this.direction === DIRECTION_EAST || this.direction === DIRECTION_WEST
    const map = link.map
    const onGrid = map && mod(sideways ? this.y - map.y : this.x - map.x, TILE_WIDTH) === 0
    this.setState(onGrid ? STATE_SLIDING : STATE_CUT)
  }

  // Into two gels, in the free slots from the last one ($FEBB)
  split (map) {
    const taken = new Set(map.activeEnemies.filter(enemy => !enemy.isDead).map(enemy => enemy.slot))
    for (const direction of ACROSS[this.direction]) {
      let slot = SLOTS
      while (taken.has(slot) && slot > 1) {
        slot--
      }
      taken.add(slot)
      map.activeEnemies.push(Gel.split(this.x, this.y, direction, slot, this.random))
    }
    if (map.room) {
      map.enemyCount++
    }
    this.uncounted = true
    this.setState(STATE_DEAD)
  }

  act (map, link) {
    this.frames++
    this.colour = COLOURS[map.type] ?? 'green'
    switch (this.state) {
      case STATE_SLIDING:
        this.slide(map)
        return
      case STATE_CUT:
        this.split(map)
        return
    }
    this.hop(map, link)
  }

  // The way of the blow, up to what stops it, looked at on each point of the grid
  slide (map) {
    const [dx, dy] = DIRECTION_VECTORS[this.direction]
    for (let i = 0; i < SLIDE_SPEED; i++) {
      const onGrid = mod(this.x - map.x, TILE_WIDTH) === 0 && mod(this.y - map.y, TILE_WIDTH) === 0
      if (onGrid && !canWalkTo(map, this.x, this.y, this.direction)) {
        this.split(map)
        return
      }
      this.x += dx
      this.y += dy
    }
  }

  hop (map, link) {
    if (this.turnFrames > 0) {
      this.turnFrames--
    }
    if (this.pause > 0) {
      this.pause--
      if (this.pause === 0) {
        chooseWay(this, map.target ?? link, ZOL)
        if (!avoidObstacle(this, map)) {
          this.pause = pick(this.random, PAUSES)
        }
      }
      return
    }
    this.fraction += SPEED
    const pixels = Math.floor(this.fraction / SPEED_UNIT)
    this.fraction -= pixels * SPEED_UNIT
    const [dx, dy] = DIRECTION_VECTORS[this.direction]
    for (let i = 0; i < pixels * NES_PIXEL; i++) {
      this.x += dx
      this.y += dy
      const offset = mod(dx !== 0 ? this.x - map.x : this.y - map.y, TILE_WIDTH)
      if (offset === 0) {
        this.pause = pick(this.random, PAUSES)
        return
      }
    }
  }

  drawBody (context) {
    drawImage(context, resource.getSprite(`zol_${this.colour ?? 'green'}_move`), Math.floor(this.frames / IMAGE_FRAMES) % 2, this.x, this.y, this.width, this.height)
  }
}
