'use strict'

// The slow timers of the ROM ($3D to $4E: a dodongo stunned, a bubble's touch…), read in bank 7 $E51E: each frame
// a counter ($26) goes down by 1; when it goes under 0, it starts again at 9 and the slow timers go down by 1 that
// frame. They go down every 10 frames, all at the same frames: one set at $10 is 0 from 151 to 160 frames later, as
// the counter goes
const SLOW_FRAMES = 10
let counter = 0
let tick = false

// One frame of the game (see Game.process)
export function stepSlowTimers () {
  counter--
  tick = counter < 0
  if (tick) {
    counter = SLOW_FRAMES - 1
  }
}

// The slow timers go down this frame
export function slowTick () {
  return tick
}

// A new game, and the tests
export function resetSlowTimers () {
  counter = 0
  tick = false
}
